"""Build the two polished PDF deliverables from audited metrics and sourced analysis."""
from pathlib import Path
import sys
import json
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import cm
from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
                                Image, PageBreak, KeepTogether)
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from src.pipeline import load_and_engineer, TARGETS, SENSORS
OUT = ROOT / 'output' / 'pdf'; OUT.mkdir(parents=True, exist_ok=True)
ASSETS = ROOT / 'artifacts' / 'report_assets'; ASSETS.mkdir(parents=True, exist_ok=True)
metrics = json.loads((ROOT/'artifacts/metrics.json').read_text(encoding='utf-8'))
df, audit = load_and_engineer(ROOT/'data/dados_sensores_aeromotion.csv')
palette = {'navy':colors.HexColor('#17324D'),'teal':colors.HexColor('#147D83'),'light':colors.HexColor('#EAF1F5'),'gray':colors.HexColor('#52616B')}
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle', parent=styles['Title'], fontName='Helvetica-Bold', fontSize=23, leading=29, textColor=palette['navy'], alignment=TA_CENTER, spaceAfter=18))
styles.add(ParagraphStyle(name='Sub', parent=styles['Normal'], fontSize=11, leading=16, textColor=palette['gray'], alignment=TA_CENTER, spaceAfter=14))
styles.add(ParagraphStyle(name='H1x', parent=styles['Heading1'], fontSize=15, leading=19, textColor=palette['navy'], spaceBefore=7, spaceAfter=8))
styles.add(ParagraphStyle(name='H2x', parent=styles['Heading2'], fontSize=11, leading=14, textColor=palette['teal'], spaceBefore=5, spaceAfter=5))
styles.add(ParagraphStyle(name='Bodyx', parent=styles['BodyText'], fontSize=9, leading=13, spaceAfter=6))
styles.add(ParagraphStyle(name='Smallx', parent=styles['BodyText'], fontSize=7.5, leading=10, textColor=palette['gray']))
styles.add(ParagraphStyle(name='HeaderCell', parent=styles['BodyText'], fontSize=6.4, leading=8, textColor=colors.white, alignment=TA_CENTER))

def P(text, style='Bodyx'): return Paragraph(text, styles[style])
def header_footer(canvas, doc):
    canvas.saveState(); w,h=A4
    canvas.setStrokeColor(palette['teal']); canvas.setLineWidth(1); canvas.line(1.7*cm,h-1.25*cm,w-1.7*cm,h-1.25*cm)
    canvas.setFont('Helvetica',7); canvas.setFillColor(palette['gray'])
    canvas.drawString(1.7*cm,.9*cm,'AeroMotion Dynamics | Projeto Integrador')
    canvas.drawRightString(w-1.7*cm,.9*cm,f'{doc.page}')
    canvas.restoreState()
def table(data, widths=None, font=7.5):
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),palette['navy']),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTNAME',(0,1),(-1,-1),'Helvetica'),('FONTSIZE',(0,0),(-1,-1),font),('LEADING',(0,0),(-1,-1),font+2),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#C7D2D9')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,palette['light']]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    return t

# Figures for the technical report.
clean = df.copy()
for _, idx in clean.groupby('id_equipamento', sort=False).groups.items():
    part=clean.loc[idx].sort_values('timestamp').set_index('timestamp')
    for c in SENSORS: part[c]=part[c].interpolate(method='time',limit=3,limit_area='inside')
    clean.loc[clean.index.intersection(idx),SENSORS]=part[SENSORS].to_numpy()
fig,ax=plt.subplots(figsize=(8,5)); sns.heatmap(clean[[*SENSORS,'tipo_falha']].corr(),annot=True,fmt='.2f',cmap='vlag',center=0,ax=ax,cbar_kws={'shrink':.8}); ax.set_title('Correlação de Pearson (exploratória)'); fig.tight_layout(); fig.savefig(ASSETS/'correlacao.png',dpi=180); plt.close(fig)
fig,axes=plt.subplots(2,1,figsize=(8,5),sharex=True)
for eid,g in clean.groupby('id_equipamento'):
    g=g.sort_values('timestamp').iloc[::50]
    axes[0].plot(g.timestamp,g.temperatura_mancal_c,label=eid,alpha=.8,lw=1)
    axes[1].plot(g.timestamp,g.vibracao_rms_mms,label=eid,alpha=.8,lw=1)
axes[0].set_ylabel('Temperatura (°C)'); axes[1].set_ylabel('Vibração (mm/s RMS)'); axes[1].set_xlabel('Timestamp'); axes[0].legend(ncol=4,fontsize=7); fig.tight_layout(); fig.savefig(ASSETS/'series.png',dpi=180); plt.close(fig)
chosen_name = metrics['model']
rf = metrics['metrics'][chosen_name]
compare = metrics['metrics']
model_labels = {'random_forest_tuned': 'Random Forest ajustado', 'extra_trees_tuned': 'Extra Trees ajustado'}

story=[Spacer(1,2.4*cm),P('RELATÓRIO TÉCNICO','CoverTitle'),P('Diagnóstico, saneamento, análise exploratória e modelagem preditiva','Sub'),P('AeroMotion Dynamics S.A. · Bancadas TURB-101 a TURB-104','Sub'),Spacer(1,1.2*cm),P('Projeto Integrador Avançado: IA e Análise de Dados em Sistemas Industriais','Sub'),P('Fonte: dados_sensores_aeromotion.csv (12.000 linhas; período de 1 jan. a 25 mar. de 2026). O dataset fornecido não contém imagens.','Sub'),PageBreak()]
story += [P('1. Escopo e método','H1x'),P('Este relatório documenta as decisões de preparação temporal e os principais achados da EDA e da modelagem. O processamento mantém a ordem cronológica, separa treino e teste em 70%/30%, ajusta imputação e escala somente no treino e pondera classes raras. Métricas descrevem apenas este conjunto fornecido; não são evidência de desempenho em produção.'),P('2. Diagnóstico estrutural','H1x')]
story.append(table([['Verificação','Resultado'],['Registros / campos',f"{audit['rows']:,} / {len(audit['columns'])}"],['Equipamentos',', '.join(audit['equipment'])],['Intervalo global único',f"{audit['global_interval_minutes']['mean']:.0f} min (desvio {audit['global_interval_minutes']['std']:.2f})"],['Chaves equipamento + timestamp','Sem duplicatas'],['Distribuição do alvo','Normal 10.560 (88,0%); classe 1: 600 (5,0%); classe 2: 480 (4,0%); classe 3: 360 (3,0%)']], [5.0*cm,11.0*cm]))
story += [Spacer(1,7),P('Ausências por sensor e bancada (%)','H2x')]
miss=[['Equipamento']+[c.replace('_',' ') for c in SENSORS]]
for eq,v in audit['equipment_missing_rate'].items(): miss.append([eq]+[f"{100*v[c]:.2f}%" for c in SENSORS])
story.append(table(miss,[2.0*cm]+[2.35*cm]*6,6.8)); story += [Spacer(1,6),P('A ausência total está entre 0% e 4,03% por variável; não há alvo nem identificadores ausentes. A série global tem passo regular de 10 minutos. As máquinas alternam leituras, por isso intervalos entre registros consecutivos da mesma bancada podem exceder 10 minutos sem indicar falha do agendamento.','Smallx'),P('3. Saneamento e features','H1x'),P(f"Os valores fora de limites de plausibilidade amplos foram convertidos em ausentes ({audit['invalid_extremes_replaced']} valores). A faixa normal do dicionário foi tratada como referência operacional, não como teto absoluto para falhas. Lacunas internas curtas foram interpoladas por tempo e equipamento, com limite de 3 amostras e sem extrapolação. No treino, lacunas restantes são preenchidas pela mediana de treino; os indicadores de imputação são preservados. O pipeline repete a interpolação separadamente no treino e no teste para impedir comunicação entre períodos."),P('Foram construídas médias e desvios padrão móveis de 1 h e 6 h para vibração e temperatura. As janelas são causais (defasagem de uma leitura) e agrupadas por equipamento. Severidade dinâmica = vibração RMS / rotação em RPM. A escala robusta reduz influência de extremos sem normalizar com estatísticas do teste.','Bodyx'),Image(str(ASSETS/'series.png'),width=16.2*cm,height=10.1*cm),PageBreak()]
story += [P("4. Analise exploratoria", "H1x"), Image(str(ASSETS/"correlacao.png"), width=15.7*cm, height=9.8*cm), P("A correlacao de Pearson e descritiva e nao demonstra causalidade. Comparacoes por regime e pairplot estao disponiveis no notebook. A agregacao pode confundir os efeitos do regime de carga."), P("5. Modelagem preditiva e avaliacao temporal", "H1x"), P("O corte cronologico reservou as primeiras 8.400 observacoes para treino e as 3.600 seguintes para teste. Pesos de classe trataram o desbalanceamento sem SMOTE. Random Forest e Extra Trees foram ajustados por RandomizedSearchCV com TimeSeriesSplit progressivo, usando somente o treino. O modelo final foi escolhido pelo recall macro medio das validacoes internas; o periodo de teste so foi usado para a avaliacao final. Isolation Forest foi treinado apenas com registros normais do treino.")]
headers = ["Modelo", "Acurácia", "Precisão<br/>macro", "Recall<br/>macro", "F1<br/>macro", "Precisão<br/>ponderada", "Recall<br/>ponderado", "F1<br/>ponderado"]
rows = [[P(label, 'HeaderCell') for label in headers]]
for name, m in compare.items():
    rows.append([model_labels[name], f"{m['accuracy']:.4f}", f"{m['precision_macro']:.4f}", f"{m['recall_macro']:.4f}", f"{m['f1_macro']:.4f}", f"{m['precision_weighted']:.4f}", f"{m['recall_weighted']:.4f}", f"{m['f1_weighted']:.4f}"])
story += [table(rows, [2.6*cm]+[1.92*cm]*7, 6.8), Spacer(1, 8)]
recalls = [rf["classification_report"][t]["recall"] for t in TARGETS[1:]]
threshold_note = "As tres classes superaram 90% de recall neste intervalo." if min(recalls) >= .90 else "O recall de ao menos uma classe ficou abaixo da meta academica de 90%."
story += [P(f"O modelo selecionado {model_labels[chosen_name]} atingiu acuracia {rf['accuracy']:.4f}, recall macro {rf['recall_macro']:.4f}, F1 macro {rf['f1_macro']:.4f} e F1 ponderado {rf['f1_weighted']:.4f}. Os recalls por classe de falha foram " + ", ".join(f"{v:.1%}" for v in recalls) + ". " + threshold_note + " A proximidade do limiar para desgaste de rolamento exige acompanhamento e validacao em campanhas independentes. Estes resultados descrevem somente este intervalo de teste e nao demonstram desempenho em campo."), P("As matrizes de confusao e a importancia das variaveis estao no notebook e em metrics.json. A importancia por impureza indica associacao preditiva, nao causalidade. A API conserva janelas temporais de 1 h e 6 h em memoria no processo; no cold-start nao ha historico completo, e a producao requer persistencia compartilhada entre replicas e validacao adicional.", "Bodyx"), P("6. Proximas etapas de validacao", "H1x"), P("Validar em campanhas independentes e equipamentos nao vistos; medir incerteza e custo de falsos negativos; auditar rotulos e sensores; calibrar alarmes com engenheiros de manutencao; e conduzir teste sombra supervisionado. O modelo nao substitui limites de seguranca nem procedimentos vigentes.")]
doc=SimpleDocTemplate(str(OUT/'relatorio_tecnico_aeromotion.pdf'),pagesize=A4,rightMargin=1.7*cm,leftMargin=1.7*cm,topMargin=1.7*cm,bottomMargin=1.4*cm,title='Relatório Técnico AeroMotion Dynamics',author='Projeto Integrador')
doc.build(story,onFirstPage=header_footer,onLaterPages=header_footer)

# Four-page technical, ethical and regulatory opinion with primary citations.
eth=[]
eth += [Spacer(1,2*cm),P('PARECER TÉCNICO, ÉTICO E REGULATÓRIO','CoverTitle'),P('Visão computacional, IA industrial, proteção de dados e cibersegurança','Sub'),P('AeroMotion Dynamics S.A. · versão acadêmica · 20 de outubro de 2026','Sub'),Spacer(1,1.4*cm),P('Objeto. Analisar condições para adoção de inspeção visual/térmica e manutenção preditiva, incluindo impactos no trabalho, LGPD, EU AI Act e segurança OT/IT. O parecer é uma análise acadêmica baseada no escopo descrito e não substitui avaliação jurídica, de segurança de máquina ou de conformidade do produto.','Bodyx'),PageBreak(),P('1. Impactos no trabalho e governança humana','H1x'),P('A automação de inspeções pode reduzir exposição a áreas quentes, repetitividade e tempo de triagem. Também pode deslocar tarefas, intensificar metas e produzir decisões opacas que afetem a avaliação de trabalhadores. A implantação deve começar com mapeamento de tarefas, consulta aos representantes, análise de riscos psicossociais e plano financiado de requalificação. Inspetores devem participar da rotulagem, da definição de critérios de aceitação, da análise de falsos alarmes e da melhoria do sistema.'),P('A trilha de formação deve incluir leitura de sinais, revisão de imagens, calibração, diagnóstico de falhas, tratamento de exceções, segurança funcional, privacidade e direito de contestar registros. A IA deve priorizar assistência e triagem. Pessoas habilitadas mantêm autoridade para inspecionar, interromper teste e liberar equipamento; não usar score do modelo para disciplina, produtividade individual ou decisões de emprego.'),P('Governança operacional: registrar versão/modelo, entrada, saída, confiança, intervenção humana e motivo; separar identificação de trabalhador da telemetria de máquina; limitar retenção; disponibilizar canal de correção; investigar impactos desiguais e erros sistemáticos. A responsabilidade final permanece com a organização que especifica, integra e utiliza o sistema.'),P('2. LGPD e câmeras no chão de fábrica','H1x'),P('Vídeos identificáveis são dados pessoais; biometria vinculada a pessoa natural é dado pessoal sensível nos termos da LGPD (arts. 5º, II e 11). Antes de instalar câmeras, definir finalidade específica de segurança/qualidade, base legal adequada para cada tratamento, necessidade e proporcionalidade, transparência, retenção e acesso. Legítimo interesse do art. 7º, IX só se aplica a dado não sensível e requer avaliação concreta de finalidade, necessidade, expectativas e salvaguardas conforme orientação da ANPD. Não é autorização automática para reconhecimento facial ou tratamento biométrico.'),P('Preferir câmera enquadrada apenas na peça e zona de teste; mascarar rostos e crachás na borda (edge) antes de armazenar/transmitir; evitar áudio e locais de descanso, sanitários e vestiários; não coletar imagens continuamente se captura acionada pelo teste for suficiente. Descartar o quadro bruto após inferência quando não houver necessidade documentada de retenção; manter apenas metadados técnicos minimizados. Quando guardar imagem para rastreabilidade, prazo e acesso devem ser justificados, segregados e auditáveis.'),P('O controlador deve documentar operações, informar trabalhadores e terceiros, atender direitos dos titulares, restringir acesso por função e avaliar relatório de impacto à proteção de dados (RIPD) antes do tratamento de maior risco. Contratos de operadores devem definir instruções, segurança e comunicação de incidentes. Reconhecimento biométrico não integra o escopo proposto e deve permanecer desabilitado.','Bodyx'),PageBreak(),P('3. EU AI Act e classificação de risco','H1x'),P('O Regulamento (UE) 2024/1689 tem aplicação territorial e material própria; a empresa deve avaliar se oferece, coloca em serviço ou utiliza o sistema na União Europeia, inclusive por integração em produto. A classificação não decorre apenas de usar visão computacional ou de operar em indústria.'),P('O Anexo III inclui usos de IA em emprego e gestão de trabalhadores, por exemplo recrutamento, decisões sobre condições de trabalho, promoção/cessação, alocação de tarefas baseada em comportamento/características e monitoramento/avaliação de desempenho. Assim, usar imagens ou previsões para avaliar trabalhadores pode enquadrar-se como alto risco. Uma solução limitada à inspeção de peça e manutenção de máquina não parece, por si só, pertencer às categorias do Anexo III; ainda pode ser componente de segurança de produto regulado no Anexo I, situação que exige análise do produto e legislação setorial. A finalidade prevista e o uso real controlam a avaliação; não é possível dar classificação definitiva sem arquitetura, mercado e integração.'),P('Se alto risco, preparar sistema de gestão de risco e qualidade, governança de dados, documentação técnica, logs, instruções, supervisão humana, precisão/robustez/cibersegurança, avaliação de conformidade, registro e monitoramento pós-mercado, conforme papel de provedor/deployer e artigos aplicáveis. O artigo 6(3) prevê condições limitadas para alguns sistemas do Anexo III que não apresentem risco significativo ou influenciem materialmente a decisão; não usar essa exceção sem análise documentada. Também verificar deveres de alfabetização em IA (art. 4) e transparência aplicáveis.'),P('4. Cibersegurança industrial OT/IT','H1x'),P('Desenhar defesa em profundidade alinhada a IEC 62443 e ao guia NIST SP 800-82 Rev. 3 para OT. Segmentar câmera, edge/API, historiador, rede de engenharia e IT em zonas/conduítes; permitir somente fluxos explicitamente necessários; negar acesso direto da API ao CLP para escrita. Inferência deve publicar recomendação para supervisão, com intertravamentos e lógica de segurança independentes.'),P('Ameaças incluem envenenamento de rótulos/dados, replay e spoofing de sensor, imagens adversariais, extração/alteração de modelo, credenciais comprometidas, ransomware e movimento lateral IT→OT. Mitigar com identidade de dispositivo e mTLS, autenticação forte, privilégios mínimos, assinatura e hash de modelo/dataset, validação de integridade, trilha de auditoria imutável, revisão de rótulos, allowlist de rede, gestão de vulnerabilidades, inventário de ativos, backups offline testados e resposta a incidentes com operação manual segura. Treinar atualizações em staging e rollback assinado; nunca experimentar diretamente em equipamento energizado.'),PageBreak(),P('5. Plano MLOps de 12 meses','H1x'),table([['Período','Controles e evidências'],['Mês 0–1','Congelar baseline; documentar dados, limiares e rótulos; teste em sombra; RIPD/model card; inventário de ativos; SLO e responsável por aprovar release.'],['Meses 2–3','Monitorar semanalmente ausência, faixa física, frequência, latência e proporção de classes; comparar PSI/KS e distribuição por equipamento/regime; revisão humana diária de alertas e falsos negativos.'],['Meses 4–6','Revisão mensal de drift e incidentes; auditoria amostral rotulada; medir recall por falha, falsos alarmes/hora e tempo de antecedência; revalidar em conjunto temporal congelado antes de retreino.'],['Meses 7–9','Teste de regressão e segurança; comparar versão candidata vs produção em shadow/canary; avaliar novos sensores, carga e manutenção; aprovar ou reverter por gate independente.'],['Meses 10–12','Revisão trimestral executiva e anual de riscos; revalidar base de referência, controles LGPD, acessos, fornecedores, calibração, benefício e impacto no trabalho; renovar ou retirar o modelo.']], [2.2*cm,13.8*cm],7),Spacer(1,8),P('Data drift é mudança nas entradas ou sua qualidade; concept drift é alteração da relação entre sinais e falhas/resultado. Sinalizar, não retreinar automaticamente: qualquer alerta abre investigação de sensor, processo, rótulo e manutenção. Exigir amostra rotulada, validação fora do tempo, recall por classe acima do limiar aprovado pela engenharia, orçamento de alarmes, teste de cibersegurança, revisão humana e plano de rollback. Congelar modelo e histórico de evidências durante investigação. Como não há imagens no CSV recebido, métricas geométricas e térmicas devem ser estabelecidas posteriormente em conjunto representativo com escala física, calibração radiométrica e verdade-terreno.'),P('6. Fontes normativas primárias','H1x'),P('Brasil. Lei nº 13.709/2018, Lei Geral de Proteção de Dados Pessoais, texto oficial: https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm','Smallx'),P('ANPD. Guia Orientativo: Hipóteses legais de tratamento de dados pessoais - Legítimo Interesse: https://www.gov.br/anpd/pt-br/centrais-de-conteudo/materiais-educativos-e-publicacoes/guia_legitimo_interesse.pdf','Smallx'),P('União Europeia. Regulamento (UE) 2024/1689, texto oficial consolidado: https://eur-lex.europa.eu/eli/reg/2024/1689','Smallx'),P('NIST. SP 800-82 Rev. 3 final, Guide to Operational Technology (OT) Security. Rev. 4 initial public draft released 21 Sep 2026; consult its status before deployment: https://csrc.nist.gov/pubs/sp/800/82/r3/final','Smallx'),P('IEC 62443. Industrial communication networks - Network and system security. Aplicar edição e partes vigentes conforme escopo contratual.','Smallx'),P('Este parecer trata requisitos gerais. Escopo internacional, produto, risco de segurança funcional e papéis de controlador/provedor devem ser confirmados por jurídico, DPO/encarregado e engenharia antes de produção.','Smallx')]
doc=SimpleDocTemplate(str(OUT/'parecer_tecnico_etico_regulatorio.pdf'),pagesize=A4,rightMargin=1.7*cm,leftMargin=1.7*cm,topMargin=1.7*cm,bottomMargin=1.4*cm,title='Parecer Técnico Ético e Regulatório AeroMotion Dynamics',author='Projeto Integrador')
doc.build(eth,onFirstPage=header_footer,onLaterPages=header_footer)
print('PDFs gravados em',OUT)
